namespace ghidra.app.plugin.core.script;

/**
 * Categories for organizing scripts in the Script Quick Launch dialog.
 */
public class ScriptGroup
{	public static readonly ScriptGroup RECENT_SCRIPTS = new();
	public static readonly ScriptGroup ALL_SCRIPTS = new();


	private string displayName;

	private ScriptGroup(string displayName) {
		this.displayName = displayName;
	}

	public string getDisplayName() {
		return displayName;
	}

	public static ScriptGroup getGroupByDisplayName(string name) {
		foreach (ScriptGroup group in values()) {
			if (group.getDisplayName().equals(name)) {
				return group;
			}
		}
		return null;
	}
}
